import { useEffect } from "react";
import { useLocation, useNavigate } from "react-router-dom";

const NavigationGuard = ({ children }) => {
  const location = useLocation();
  const navigate = useNavigate();

  useEffect(() => {
    // Get last valid path from sessionStorage, default to /home
    const lastValidPath = sessionStorage.getItem("lastValidPath") || "/home";
    // If navigation is not triggered by app, redirect back
    if (!(location.state && location.state.navigation_intent)) {
      if (location.pathname !== lastValidPath) {
        navigate(lastValidPath, { replace: true });
      }
    } else {
      // If navigation is valid, update last valid path
      sessionStorage.setItem("lastValidPath", location.pathname);
    }
  }, [location, navigate]);

  return children;
};

export default NavigationGuard;
